<?php
// Phase 7 API tests: phone normalisation and lookup, manual call logs, handoffs, notes, dispositions, callbacks (real worker), timeline, history, reports, permissions.
declare(strict_types=1);
$base = rtrim($argv[1] ?? 'http://127.0.0.1:8000', '/') . '/api'; $root = dirname(__DIR__, 2); $results = []; $jars = []; $tok = [];
$cfgFile = getenv('LTI_CONFIG'); $cfg = require $cfgFile; $pdo = new PDO("mysql:host={$cfg['db']['host']};dbname={$cfg['db']['name']};charset=utf8mb4", $cfg['db']['user'], $cfg['db']['pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_EMULATE_PREPARES => false]);
$q = function ($sql) use ($pdo) { return $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); }; $one = function ($sql) use ($q) { $r = $q($sql); return $r ? array_values($r[0])[0] : null; };
$worker = function () use ($root, $cfgFile) { return (string)shell_exec('LTI_CONFIG=' . escapeshellarg($cfgFile) . ' php ' . escapeshellarg("$root/server/app/bin/worker.php") . ' --once 2>&1'); };
function rq(string $who, string $m, string $p, $b = null): array { global $base, $jars, $tok; $jars[$who] = $jars[$who] ?? tempnam(sys_get_temp_dir(), 'jar'); $ch = curl_init($base . $p); $hd = ['Accept: application/json']; if (!empty($tok[$who]) && $m !== 'GET') $hd[] = 'X-CSRF-Token: ' . $tok[$who];
  if ($b !== null) { $hd[] = 'Content-Type: application/json'; curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($b)); } curl_setopt_array($ch, [CURLOPT_CUSTOMREQUEST => $m, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => $hd, CURLOPT_COOKIEJAR => $jars[$who], CURLOPT_COOKIEFILE => $jars[$who]]);
  $r = curl_exec($ch); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); $ct = (string)curl_getinfo($ch, CURLINFO_CONTENT_TYPE); curl_close($ch); return [$c, json_decode((string)$r, true) ?? [], (string)$r, $ct]; }
function login(string $who, string $e): void { global $tok; [$c, $d] = rq($who, 'POST', '/auth/login', ['email' => $e, 'password' => 'Dev-Password-2026']); if ($c !== 200) throw new Exception("login $e $c"); $tok[$who] = $d['csrf']; }
function t(string $n, callable $f): void { global $results; try { $results[] = [$n, true, (string)$f()]; } catch (Throwable $e) { $results[] = [$n, false, $e->getMessage()]; } }
function ok($c, string $m): void { if (!$c) throw new Exception($m); }
foreach (['own' => 'owner@lti.test', 'adm' => 'admin@lti.test', 'adv' => 'advisor@lti.test', 'adv2' => 'advisor2@lti.test', 'fin' => 'finance@lti.test', 'sal' => 'sales@lti.test', 'trv' => 'traveler@lti.test'] as $k => $e) login($k, $e);
$tz = new DateTimeZone('America/New_York'); $now = new DateTime('now', $tz); $L = function (string $mod) use ($tz) { return (new DateTime('now', $tz))->modify($mod)->format('Y-m-d\TH:i'); };
$amalfi = (int)$one("SELECT id FROM trips WHERE name='Amalfi Coast Anniversary'"); $shah = (int)$one("SELECT id FROM contacts WHERE email='shah@example.com'"); $okafor = (int)$one("SELECT id FROM contacts WHERE email='okafor@example.com'");
$adv = (int)$one("SELECT id FROM users WHERE email='advisor@lti.test'"); $adv2 = (int)$one("SELECT id FROM users WHERE email='advisor2@lti.test'"); $S = [];
t('Calling capability: only external dialing and manual logging; PSTN, provider and WebRTC unavailable', function () { [$c, $d] = rq('adv', 'GET', '/calls/capability');
  $av = array_column(array_filter($d['modes'], function ($m) { return $m['available']; }), 'code'); ok($c === 200 && $av === ['external_dialing', 'manual_logging'] && $d['pstn']['available'] === false && in_array('hold', $d['unavailableControls'], true), json_encode($d)); return 'available: ' . implode(', ', $av) . '; PSTN unavailable'; });
t('Phone normalisation is conservative and country-aware', function () { $cases = [['(512) 555-0177', 'US', '+15125550177'], ['+44 20 7946 0958', 'US', '+442079460958'], ['020 7946 0958', 'GB', '+442079460958'], ['0917 123 4567', 'PH', '+639171234567'], ['06 1234 5678', 'IT', '+390612345678'], ['011 33 1 42 68 53 00', 'US', '+33142685300'], ['555-1234', 'US', null], ['+999 123456789', 'US', null], ['(123) 555-0177', 'US', null]];
  $bad = []; foreach ($cases as [$n, $c, $exp]) { [, $d] = rq('adv', 'GET', '/phone/lookup?number=' . urlencode($n) . "&country=$c"); if ($d['normalized']['e164'] !== $exp) $bad[] = "$n/$c => " . var_export($d['normalized']['e164'], true); }
  ok(!$bad, implode('; ', $bad)); return count($cases) . ' cases incl. US, UK, Philippines, Italy, 011 prefix; short, unknown-code and invalid-area numbers rejected'; });
t('TC03–TC05 Contact match by stored number; unknown number; hidden contacts never revealed', function () use ($shah, $okafor) { [, $m] = rq('adv', 'GET', '/phone/lookup?number=' . urlencode('512.555.0177'));
  [, $u] = rq('adv', 'GET', '/phone/lookup?number=' . urlencode('+1 212 555 0199')); [, $h] = rq('adv', 'GET', '/phone/lookup?number=' . urlencode('+1 (404) 555-0119')); [, $h2] = rq('adv2', 'GET', '/phone/lookup?number=' . urlencode('+1 (404) 555-0119'));
  ok($m['matches'][0]['contactId'] === $shah && $u['known'] === false && $u['normalized']['e164'] === '+12125550199' && $h['matches'] === [] && strpos(json_encode($h), 'Okafor') === false && $h2['matches'][0]['contactId'] === $okafor, json_encode([$m['matches'], $u['known'], $h['matches'], $h2['matches']]));
  return 'Shah matched from 512.555.0177; unknown number normalised, no match; Okafor (another advisor’s client) not revealed to advisor, visible to advisor2'; });
t('Multiple numbers per contact, preferred number, duplicates among visible contacts', function () use ($shah, $one) { [$c, $d] = rq('adv', 'POST', "/contacts/$shah/phones", ['phone' => '+44 7700 900123', 'label' => 'work']); [$c2] = rq('adv', 'POST', "/contacts/$shah/phones", ['phone' => '+447700900123']);
  [, $l] = rq('adv', 'GET', '/phone/lookup?number=' . urlencode('07700 900123') . '&country=GB'); [$c3] = rq('adv', 'POST', "/contacts/$shah/phones", ['phone' => '12']);
  ok($c === 200 && count($d['items']) === 2 && $d['items'][0]['preferred'] === true && $c2 === 409 && $l['matches'][0]['contactId'] === $shah && $c3 === 422, "$c $c2 $c3"); return '2 numbers (preferred first); duplicate 409; UK national format matched; invalid 422'; });
t('TC06–TC07 Phone-app handoff records an attempt only: not connected, no duration', function () use (&$S, $shah, $amalfi, $one) { [$c, $d] = rq('adv', 'POST', '/calls/handoff', ['contactId' => $shah, 'tripId' => $amalfi]); $S['h'] = $d['call']['id'];
  $r = $one("SELECT CONCAT_WS('|',source,verification,status,IFNULL(duration_seconds,'null'),duration_source) FROM calls WHERE id={$S['h']}");
  ok($c === 200 && $d['telUri'] === 'tel:+15125550177' && $r === 'external_handoff|handoff_unconfirmed|attempted|null|unknown' && $d['call']['statusLabel'] === 'Dial handoff — outcome not recorded' && (int)$one("SELECT COUNT(*) FROM domain_events WHERE event_type='call.logged' AND entity_id={$S['h']}") === 0, "$c $r");
  return "tel:+15125550177; stored as $r; no call.logged event"; });
t('Handoff outcome entered by staff (no invented duration); cannot be recorded twice', function () use (&$S, $one) { $disp = (int)$one("SELECT id FROM call_dispositions WHERE code='no_answer'");
  [$c0] = rq('adv', 'POST', "/calls/{$S['h']}/outcome", ['status' => 'no_answer', 'durationSeconds' => 30]); [$c, $d] = rq('adv', 'POST', "/calls/{$S['h']}/outcome", ['status' => 'no_answer', 'dispositionId' => $disp, 'notes' => 'Rang out']); [$c2] = rq('adv', 'POST', "/calls/{$S['h']}/outcome", ['status' => 'connected']);
  ok($c0 === 422 && $c === 200 && $d['call']['status'] === 'no_answer' && $d['call']['durationSeconds'] === null && $d['call']['verification'] === 'user_entered' && $c2 === 409, "$c0 $c $c2"); return 'duration on unanswered call 422; outcome no_answer, duration null; second outcome 409'; });
t('TC08–TC11 Manual outbound and inbound logs with notes and disposition; verified in MySQL', function () use (&$S, $shah, $amalfi, $L, $one) { $int = (int)$one("SELECT id FROM call_dispositions WHERE code='interested'"); $cbr = (int)$one("SELECT id FROM call_dispositions WHERE code='callback_requested'");
  [$c1, $o] = rq('adv', 'POST', '/calls', ['direction' => 'outbound', 'status' => 'connected', 'contactId' => $shah, 'tripId' => $amalfi, 'startedAt' => $L('-2 hours'), 'durationSeconds' => 754, 'dispositionId' => $int, 'notes' => 'Discussed Capri boat options']); $S['out'] = $o['call']['id'];
  [$c2, $i] = rq('adv', 'POST', '/calls', ['direction' => 'inbound', 'status' => 'missed', 'phone' => '+1 (646) 555-0100', 'startedAt' => $L('-1 hour'), 'dispositionId' => $cbr]); $S['in'] = $i['call']['id'];
  [$c3] = rq('adv', 'POST', '/calls', ['direction' => 'outbound', 'status' => 'missed', 'contactId' => $shah]); [$c4] = rq('adv', 'POST', '/calls', ['direction' => 'outbound', 'status' => 'connected', 'contactId' => $shah, 'startedAt' => $L('+1 day')]);
  [$c5] = rq('adv', 'POST', '/calls', ['direction' => 'outbound', 'status' => 'connected', 'contactId' => $shah, 'startedAt' => $L('-3 hours'), 'endedAt' => $L('-4 hours')]);
  $ro = $one("SELECT CONCAT_WS('|',source,verification,direction,status,phone_e164,contact_id,trip_id,duration_seconds,duration_source,disposition) FROM calls WHERE id={$S['out']}"); $ri = $one("SELECT CONCAT_WS('|',direction,status,phone_e164,IFNULL(contact_id,'none'),IFNULL(duration_seconds,'null')) FROM calls WHERE id={$S['in']}");
  $note = $one("SELECT body FROM call_notes WHERE call_id={$S['out']}");
  ok($c1 === 201 && $c2 === 201 && $c3 === 422 && $c4 === 422 && $c5 === 422 && $ro === "manual_log|user_entered|outbound|connected|+15125550177|$shah|$amalfi|754|entered|interested" && $ri === 'inbound|missed|+16465550100|none|null' && $note === 'Discussed Capri boat options', json_encode([$c1, $c2, $c3, $c4, $c5, $ro, $ri]));
  return "outbound: $ro; inbound missed from unknown number: $ri; invalid combinations 422"; });
t('TC13–TC14 Link call to contact and trip by editing; edit history kept', function () use (&$S, $okafor, $amalfi, $shah, $one) { [, $g] = rq('adv', 'GET', "/calls/{$S['in']}"); [$c, $d] = rq('adv', 'PUT', "/calls/{$S['in']}", ['contactId' => $shah, 'tripId' => $amalfi, 'version' => $g['call']['version']]);
  [$c2] = rq('adv', 'PUT', "/calls/{$S['in']}", ['contactId' => $okafor]);
  ok($c === 200 && $d['call']['contact']['id'] === $shah && $d['call']['trip']['id'] === $amalfi && $c2 === 404 && in_array('edited', array_column($d['call']['history'], 'event'), true), "$c $c2"); return 'linked to Shah + Amalfi; linking a hidden contact 404; edit recorded'; });
t('Notes: add, author edits; others cannot edit', function () use (&$S, $one) { [, $d] = rq('adv', 'POST', "/calls/{$S['out']}/notes", ['body' => 'Client prefers morning calls']); $nid = end($d['call']['notes'])['id'];
  [$c] = rq('adv', 'PUT', "/call-notes/$nid", ['body' => 'Client prefers calls before 10am']); [$c2] = rq('sal', 'PUT', "/call-notes/$nid", ['body' => 'x']);
  ok($c === 200 && $c2 === 403 && $one("SELECT body FROM call_notes WHERE id=$nid") === 'Client prefers calls before 10am' && (int)$one("SELECT COUNT(*) FROM call_events WHERE call_id={$S['out']} AND event='note_edited'") === 1, "$c $c2"); return 'note added and edited by author (history kept); sales 403'; });
t('Dispositions are configurable by administrators and audited', function () use ($one) { [$c, $d] = rq('adm', 'POST', '/call-dispositions', ['label' => 'Quote sent', 'requiresFollowup' => true]); $id = (int)$one("SELECT id FROM call_dispositions WHERE code='quote_sent'");
  [$c2] = rq('adm', 'PUT', "/call-dispositions/$id", ['label' => 'Quote sent by email', 'isActive' => false]); [$c3] = rq('adv', 'POST', '/call-dispositions', ['label' => 'x']);
  ok($c === 200 && count($d['items']) === 12 && $c2 === 200 && $one("SELECT CONCAT(label,'|',is_active) FROM call_dispositions WHERE id=$id") === 'Quote sent by email|0' && $c3 === 403 && (int)$one("SELECT COUNT(*) FROM audit_log WHERE action LIKE 'call_disposition.%'") === 2, "$c $c2 $c3"); return '11 seeded + 1 added; edited/deactivated; advisor 403; 2 audit entries'; });
t('TC15–TC17 Callback: task created, reminder queued, reschedule moves task and reminder, completion completes task', function () use (&$S, $shah, $L, $one, $adv) {
  [$c, $d] = rq('adv', 'POST', '/callbacks', ['callId' => $S['in'], 'scheduledAt' => $L('+1 day'), 'notes' => 'Call back about deposit']); $cb = $d['callback'];
  $task = $q = $GLOBALS['q']("SELECT * FROM tasks WHERE id=" . (int)$cb['taskId'])[0]; $job = $one("SELECT COUNT(*) FROM scheduled_jobs WHERE dedupe_key='cb:{$cb['id']}:0' AND status='pending'");
  ok($c === 201 && $cb['contactId'] === $shah && $task['title'] === 'Call back Daniel Shah' && (int)$task['assigned_to'] === $adv && $task['source'] === 'Callback' && (int)$job === 1, "$c " . json_encode($cb));
  [$c2, $r] = rq('adv', 'POST', "/callbacks/{$cb['id']}/reschedule", ['scheduledAt' => $L('+2 days'), 'reason' => 'Client travelling']); $newDue = substr($L('+2 days'), 0, 10);
  ok($c2 === 200 && $r['callback']['rescheduleCount'] === 1 && $one("SELECT due_date FROM tasks WHERE id={$cb['taskId']}") === $newDue && $one("SELECT status FROM scheduled_jobs WHERE dedupe_key='cb:{$cb['id']}:0'") === 'cancelled' && (int)$one("SELECT COUNT(*) FROM scheduled_jobs WHERE dedupe_key='cb:{$cb['id']}:1' AND status='pending'") === 1, "resched $c2");
  [$c3, $x] = rq('adv', 'POST', "/callbacks/{$cb['id']}/complete"); [$c4] = rq('adv', 'POST', "/callbacks/{$cb['id']}/complete");
  ok($c3 === 200 && $x['callback']['status'] === 'completed' && $one("SELECT status FROM tasks WHERE id={$cb['taskId']}") === 'completed' && $one("SELECT status FROM scheduled_jobs WHERE dedupe_key='cb:{$cb['id']}:1'") === 'cancelled' && $c4 === 409, "complete $c3 $c4");
  $S['cbTask'] = $cb['taskId']; return 'task “Call back Daniel Shah” + reminder; reschedule moved due date and replaced reminder; completion closed task, cancelled reminder'; });
t('Callback reminder delivered by the real worker when due; overdue filter', function () use ($shah, $L, $one, $adv, $worker, $pdo) { [, $d] = rq('adv', 'POST', '/callbacks', ['contactId' => $shah, 'scheduledAt' => $L('-1 minute')]); $id = $d['callback']['id'];
