  ok(in_array($id, array_column($o['items'], 'id'), true) && $n === 1, "overdue/notif $n"); return 'listed as overdue; worker delivered one reminder notification'; });
t('TC18 Call activity appears on the contact and trip timelines', function () use ($shah, $amalfi) { [, $c] = rq('adv', 'GET', "/activity?entityType=contact&entityId=$shah"); [, $t] = rq('adv', 'GET', "/activity?entityType=trip&entityId=$amalfi");
  $ct = array_column($c['items'], 'type'); $tt = array_column($t['items'], 'type'); foreach (['call.logged', 'call.note', 'callback.scheduled', 'callback.rescheduled', 'callback.completed'] as $e) ok(in_array($e, $ct, true), "contact missing $e"); ok(in_array('call.logged', $tt, true), 'trip missing call.logged');
  $sum = $c['items'][array_search('call.logged', $ct, true)]['summary']; return 'contact and trip timelines include call events, e.g. “' . $sum . '”'; });
t('TC19–TC21 History filters: direction, staff, missed, follow-up, search by phone and contact, sort', function () use (&$S, $adv, $shah) {
  [, $in] = rq('adv', 'GET', '/calls?direction=inbound'); [, $st] = rq('own', 'GET', "/calls?staffId=$adv"); [, $mi] = rq('adv', 'GET', '/calls?status=missed'); [, $fu] = rq('adv', 'GET', '/calls?status=followup');
  [, $ph] = rq('adv', 'GET', '/calls?q=6465550100'); [, $nm] = rq('adv', 'GET', '/calls?q=Shah'); [, $asc] = rq('adv', 'GET', '/calls?sort=asc');
  $dirs = array_unique(array_column($in['items'], 'direction')); ok($dirs === ['inbound'] && count($st['items']) >= 3 && array_unique(array_column($st['items'], 'staffId')) === [$adv] && in_array($S['in'], array_column($mi['items'], 'id'), true)
    && in_array($S['out'], array_column($fu['items'], 'id'), true) && array_column($ph['items'], 'id') === [$S['in']] && in_array($S['out'], array_column($nm['items'], 'id'), true) && $asc['items'][0]['startedAt'] <= end($asc['items'])['startedAt'], 'filters');
  return 'inbound only; by staff; missed; follow-up (disposition requires follow-up); search 6465550100 -> 1; search Shah; ascending sort'; });
t('TC22 Reporting totals equal MySQL counts and are labelled as unverified', function () use ($one) { [, $r] = rq('own', 'GET', '/calls/report');
  $n = (int)$one('SELECT COUNT(*) FROM calls WHERE archived_at IS NULL'); $dur = (int)$one("SELECT COALESCE(SUM(duration_seconds),0) FROM calls WHERE duration_source='entered' AND archived_at IS NULL"); $out = (int)$one("SELECT COUNT(*) FROM calls WHERE direction='outbound' AND archived_at IS NULL");
  $byDir = array_column($r['byDirection'], 'count', 'key'); $cbDone = (int)$one("SELECT COUNT(*) FROM callbacks WHERE status='completed'");
  ok($r['totals']['records'] === $n && $r['totals']['enteredDurationSeconds'] === $dur && $byDir['outbound'] === $out && $r['totals']['verifiedCalls'] === 0 && $r['callbacks']['completed'] === $cbDone && strpos($r['note'], 'None are verified') !== false, json_encode($r['totals']));
  return "records $n, entered duration {$dur}s, outbound $out, verified 0, callbacks completed $cbDone — all match SQL"; });
t('Call export (CSV) respects scope', function () use (&$S) { [$c, , $csv, $ct] = rq('adv', 'GET', '/calls/export'); [, , $csv2] = rq('adv2', 'GET', '/calls/export');
