t('TC25 Call logs persist across logout and a new login', function () use (&$S) { rq('adv', 'POST', '/auth/logout'); login('adv', 'advisor@lti.test'); [, $l] = rq('adv', 'GET', '/calls'); [, $d] = rq('adv', 'GET', "/calls/{$S['out']}");
