t('TC27 No fictional durations: only staff-entered durations exist and none on unanswered calls', function () use ($one) { $bad = (int)$one("SELECT COUNT(*) FROM calls WHERE (duration_seconds IS NOT NULL AND duration_source<>'entered') OR (status<>'connected' AND duration_seconds>0) OR (source='external_handoff' AND status='attempted' AND duration_seconds IS NOT NULL)");
