t('TC35 Every record carries an accurate source and verification label', function () { [, $l] = rq('own', 'GET', '/calls?perPage=200'); $pairs = array_unique(array_map(function ($x) { return $x['source'] . '/' . $x['verification']; }, $l['items']));
